      const pageAdd=event.target.closest('[data-page-add]');if(pageAdd){event.stopPropagation();const scope=pageAdd.dataset.pageAdd,container=pageAdd.closest('.template-wizard,form'),template=scope==='draft'?state.uploadDraft:selectedTemplate();syncFieldConfigInputs(container,scope);addTemplatePage(template);scope==='draft'?renderTemplateWizard():templateFieldsDialog();return;}
