      const formulaEdit=event.target.closest('[data-formula-edit]');if(formulaEdit){event.stopPropagation();const scope=formulaEdit.dataset.formulaScope,container=formulaEdit.closest('.template-wizard,form'),template=scope==='draft'?state.uploadDraft:selectedTemplate();syncFieldConfigInputs(container,scope);const field=template.fields.find(item=>item.key===formulaEdit.dataset.formulaEdit);if(field){field.type='formula';state.formulaBuilder={scope,key:field.key,expression:field.formula||''};scope==='draft'?renderTemplateWizard():templateFieldsDialog();}return;}
