  function syncFieldConfigInputs(container,scope) {const template=scope==='draft'?state.uploadDraft:selectedTemplate();if(!template||!container)return;normalizeTemplatePages(template);container.querySelectorAll(`[data-page-title="${scope}"]`).forEach(input=>{const page=template.pages.find(item=>item.number===Number(input.dataset.pageNumber));if(page)page.title=input.value.trim()||`หน้า ${page.number}`;});container.querySelectorAll(`[data-${scope}-label]`).forEach(input=>{template.fields[Number(input.dataset[`${scope}Label`])].label=input.value;});container.querySelectorAll(`[data-${scope}-type]`).forEach(input=>{template.fields[Number(input.dataset[`${scope}Type`])].type=input.value;});container.querySelectorAll(`[data-${scope}-options]`).forEach(input=>{template.fields[Number(input.dataset[`${scope}Options`])].options=input.value.split('|').map(item=>item.trim()).filter(Boolean);});container.querySelectorAll(`[data-${scope}-page]`).forEach(input=>{template.fields[Number(input.dataset[`${scope}Page`])].page=Number(input.value);});container.querySelectorAll(`[data-${scope}-required]`).forEach(input=>{template.fields[Number(input.dataset[`${scope}Required`])].required=input.checked;});}
