    equipment:{label:'อุปกรณ์',headers:['work_group_id','site_id','equipment_id','equipment_type','equipment_name','model','serial_number','location','latitude','longitude'],sample:[['FY2569','SITE-A','SM4','Soil Moisture Sensor','Soil Moisture Sensor','SM-100','SMS-2026-004','Zone D','13.499100','100.994200']]},
