  function dailyModeSwitch(){return `<nav class="daily-mode-switch" aria-label="ประเภทรายงาน"><button type="button" class="${state.dailyMode==='daily'?'active':''}" data-daily-mode="daily">รายงานประจำวัน</button><button type="button" class="${state.dailyMode==='weather'?'active':''}" data-daily-mode="weather">รายงานสภาพอากาศ <small>เหตุการณ์ที่ไม่สามารถทำงานได้</small></button></nav>`;}
