  function quantityEditor(scope,key,item){return `<article class="daily-qty-card"><span><strong>${esc(item.label)}</strong><small>${Number(item.qty||0)>0?'ใช้งานวันนี้':'ไม่มีรายการ'}</small></span><div><button type="button" data-daily-qty="-1" data-daily-scope="${scope}" data-daily-key="${key}" aria-label="ลดจำนวน ${esc(item.label)}">−</button><input type="number" min="0" step="1" name="${scope}_${key}" value="${Number(item.qty||0)}" inputmode="numeric" aria-label="จำนวน ${esc(item.label)}"><button type="button" data-daily-qty="1" data-daily-scope="${scope}" data-daily-key="${key}" aria-label="เพิ่มจำนวน ${esc(item.label)}">＋</button></div></article>`;}
