  function syncDailyForm(){const form=root().querySelector('[data-daily-form]');if(!form)return null;const report=ensureDailyReport(state.dailyDate,form.dataset.dailySiteId);dailyPeople.forEach(([key])=>report.people[key].qty=Math.max(0,Number(form.elements[`people_${key}`]?.value||0)));dailyMachines.forEach(([key])=>report.machines[key].qty=Math.max(0,Number(form.elements[`machines_${key}`]?.value||0)));report.note=form.elements.note?.value.trim()||'';form.querySelectorAll('[data-daily-detail-row]').forEach((row,index)=>{const item=report.details.find(detail=>detail.id===row.dataset.dailyDetailRow);if(item){item.description=row.querySelector('[data-daily-description]').value.trim();item.remark=row.querySelector('[data-daily-remark]').value;item.time=row.querySelector('[data-daily-time]').value;item.order=index;}});return report;}
