    const sheets=allDataSheets(),group=selectedGroup();if(!sheets.length)return alert('กลุ่มงานนี้ยังไม่มีอุปกรณ์สำหรับ Export');if(!window.WorkHubReportXlsx)return alert('ยังโหลดตัวสร้าง Excel ไม่สำเร็จ กรุณารีเฟรชแล้วลองใหม่');const button=root().querySelector('[data-export-all-data]');if(button)button.disabled=true;try{await withExportProgress('กำลัง Export ข้อมูลทั้งหมด',async update=>{update(25,`กำลังจัดข้อมูล ${sheets.length} Sheet…`);const blob=await window.WorkHubReportXlsx.createWorkbook(sheets);update(92,'กำลังเตรียมไฟล์ดาวน์โหลด…');download(`${slug(group?.code||group?.name)}_all_data_${fileTimestamp()}.xlsx`,blob);});notify(`Export Excel แล้ว ${sheets.length} Sheet · ${sheets.reduce((sum,sheet)=>sum+sheet.rows.length,0)} ID`);}catch(error){alert(error.message);}finally{if(button)button.disabled=false;}
