  function saveReportForm(form) {const equipment=state.data.equipment.find(item=>item.uid===form?.dataset.equipment),template=equipment&&templateForEquipment(equipment);if(!equipment||!template)return null;const report=ensureReport(equipment),values=Object.fromEntries(new FormData(form));Object.entries(values).forEach(([field,value])=>{report.values[field]=String(value).trim();});report.values=calculateFormulaFields(template,report.values);report.updatedAt=nowText();save();return {equipment,template,report};}
