  async function activate(force){if(!state.data||force){if(!state.loading)state.loading=load().finally(()=>{state.loading=null;});await state.loading;}state.active='reports';state.selectedProvinces.clear();state.provinceFilterExplicit=false;state.provinceFilterOpen=false;const favoriteGroup=state.data.groups.find(group=>group.id===state.favorites.groupId);if(favoriteGroup){state.selectedGroup=favoriteGroup.id;state.selectedSite='';state.selectedEquipment='';state.reportStep='sites';}else state.reportStep='groups';if(!root().querySelector('.module-shell')||force)shell();else render();startRemoteRefresh();}
